"use client";

import { adminFetch } from "@/lib/admin-api";

export interface ExportParams {
  section?: string;
  format: "csv" | "xls";
  from?: string;
  to?: string;
  status?: string;
  category?: string;
  supplier?: string;
  submitter?: string;
  source?: string;
  mark_exported?: boolean;
}

/** Exports are generated by the admin API (audited, RLS-independent) and saved through the browser. */
export async function downloadExport(p: ExportParams): Promise<void> {
  const q = new URLSearchParams();
  for (const [k, v] of Object.entries(p)) {
    if (v === undefined || v === "" || v === false) continue;
    q.set(k, String(v));
  }
  // dates here are Riyadh calendar days (yyyy-MM-dd); the API compares timestamptz, so widen to full days
  if (p.from) q.set("from", `${p.from}T00:00:00+03:00`);
  if (p.to) q.set("to", `${p.to}T23:59:59.999+03:00`);
  const res = await adminFetch(`/admin/export?${q.toString()}`);
  const blob = await res.blob();
  const name = /filename="([^"]+)"/.exec(res.headers.get("content-disposition") ?? "")?.[1] ?? `expenses.${p.format}`;
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = name;
  document.body.append(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}
